do $$declare s text; needle text:=$n$'study_settings',private.qa_visible_studies(ctx),$n$; replacement text:=$r$'specialist_progress',case when ctx->>'kpi_specialist'='true' then (select jsonb_agg(to_jsonb(g) order by g.label) from (select groups.label,count(r.id) as assigned,count(r.id) filter(where r.status='completed') as completed,count(r.id) filter(where r.status='in_progress') as in_progress,count(r.id) filter(where r.status='pending') as pending,(select count(*) from private.qa_reviews old where old.analyst_id=(ctx->>'id')::uuid and old.day<v_day and old.status<>'completed' and old.study=any(groups.studies)) as previous_pending from (values ('CAM',array['Moderno','Tradicional']),('Lindley',array['Lindley']),('Chile',array['Chile'])) groups(label,studies) left join private.qa_reviews r on r.analyst_id=(ctx->>'id')::uuid and r.day=v_day and r.study=any(groups.studies) group by groups.label,groups.studies) g) else '[]'::jsonb end,'study_settings',private.qa_visible_studies(ctx),$r$;begin select pg_get_functiondef('private.qa_api(text,jsonb)'::regprocedure) into s;if strpos(s,'specialist_progress')=0 then if strpos(s,needle)=0 then raise exception 'No se encontro configuracion';end if;execute replace(s,needle,replacement);end if;end;$$;
